#!/usr/bin/env node
// Android versionCode monotonicity gate.
//
// WHY THIS CHECKS tauri.conf.json, NOT tauri.properties
// -----------------------------------------------------
// `src-tauri/gen/android/app/tauri.properties` carries the effective
// `tauri.android.versionCode`, but it is AUTOGENERATED ("THIS IS AN AUTOGENERATED
// FILE. DO NOT EDIT THIS FILE DIRECTLY") and git-ignored
// (src-tauri/gen/android/app/.gitignore: `/tauri.properties`). The only *tracked*
// input to it is the `version` field in src-tauri/tauri.conf.json, from which Tauri
// derives versionCode as major*1_000_000 + minor*1_000 + patch (0.1.0 -> 1000).
// So the tracked thing to gate is `version`, and this script ALSO re-derives the
// versionCode so the Android-facing number is checked explicitly rather than by
// proxy. If the file is present locally (it is after any Android build) the
// derived code is cross-checked against it.
//
// The failure this prevents: a duplicate versionCode is accepted by Play/adb
// silently — the install just refuses to replace the old one, or worse succeeds
// against a stale build, and nobody notices until users report "the update didn't
// land".
//
// Semantics: an UNCHANGED version is fine (most PRs are not releases). A CHANGED
// version must be STRICTLY GREATER. A decrease or a non-semver version fails.
//
// Usage:  node scripts/check-android-versioncode.mjs
//   env AEGIS_BASE_REF  git ref to compare against. Locally the default is
//                       origin/main; in CI it is deliberately UNSET unless the
//                       workflow provides it, and then the gate SKIPS itself
//                       loudly. See below — this is not a nit, it is the whole
//                       gate.
import { execFileSync } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const REPO_ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const CONF_REL = 'src-tauri/tauri.conf.json';
const PROPS_REL = 'src-tauri/gen/android/app/tauri.properties';

// WHY THE DEFAULT IS NOT `origin/main` IN CI. It used to be, unconditionally, and
// this gate had teeth on exactly one of its three triggers. `ci.yml` runs on
// `push: main`, `pull_request` and a weekly `schedule`; on a push to main and on a
// schedule, HEAD *is* `origin/main`, so the script compared the working tree with
// itself, printed "version unchanged from origin/main" and passed. A versionCode
// DECREASED on main — which Android refuses to install as a downgrade — was
// therefore only ever caught on a PR, and only by luck if the PR's own run saw it.
//
// So: AEGIS_BASE_REF wins; a local run with nothing set keeps `origin/main` (that
// is the useful thing to check against on a branch); a CI run with nothing set has
// NO base and says so, loudly, instead of comparing the file with itself. The
// coverage ratchets resolve their base the same way — see `resolveBaselineBaseRef`
// in coverageCheck.mjs — so all three gates answer "what am I comparing against"
// with the same rules.
const IS_CI = process.env.GITHUB_ACTIONS === 'true';
const BASE_REF = process.env.AEGIS_BASE_REF || (IS_CI ? '' : 'origin/main');

if (!BASE_REF) {
  console.log(
    '::warning::No base ref available — SKIPPING the Android versionCode monotonicity ' +
      'check. AEGIS_BASE_REF is unset and this is a CI run, so there is no earlier ' +
      'commit to compare against; comparing against the current HEAD would be a file ' +
      'against itself and would always pass. ci.yml sets AEGIS_BASE_REF from the ' +
      'event, and a push to main is what checks the merged result. This is not a pass.',
  );
  process.exit(0);
}

const fail = (msg) => {
  console.error(`::error::${msg}`);
  process.exit(1);
};

const readAtRef = (ref) =>
  execFileSync('git', ['show', `${ref}:${CONF_REL}`], {
    cwd: REPO_ROOT,
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'pipe'],
  });

/** Read `version` out of tauri.conf.json with a real parse.
 *
 * This used to be `/"version"\s*:\s*"([^"]+)"/`, which matches the FIRST
 * `"version"` key anywhere in the file at ANY nesting depth — so a nested object
 * preceding the top-level key would silently supply the app version, and the
 * gate would compare the wrong string. A version check is exactly the kind of
 * gate that must not fail in the "looks fine" direction. The stated reason for
 * the regex ("without pulling in a JSONC parser") never applied: `tauri.conf.json`
 * is machine-generated config that Tauri itself reads, not JSONC.
 */
function versionOf(jsonText, label) {
  let parsed;
  try {
    parsed = JSON.parse(jsonText);
  } catch (err) {
    fail(`${label}: ${CONF_REL} is not valid JSON: ${err.message}`);
  }
  const version = parsed && typeof parsed === 'object' ? parsed.version : undefined;
  if (typeof version !== 'string') {
    fail(`${label}: no "version" field found in ${CONF_REL}.`);
  }
  return version;
}

/** Tauri/android versionCode = major * 1_000_000 + minor * 1_000 + patch. */
function versionCodeOf(version, label) {
  const m = /^(\d+)\.(\d+)\.(\d+)$/.exec(version);
  if (!m) return null;
  return Number(m[1]) * 1_000_000 + Number(m[2]) * 1_000 + Number(m[3]);
}

/** Semver-ish ordering: only comparable when both sides are MAJOR.MINOR.PATCH. */
function compare(a, b) {
  const pa = /^(\d+)\.(\d+)\.(\d+)$/.exec(a);
  const pb = /^(\d+)\.(\d+)\.(\d+)$/.exec(b);
  if (!pa || !pb) return null;
  for (let i = 1; i <= 3; i++) {
    const d = Number(pa[i]) - Number(pb[i]);
    if (d !== 0) return d < 0 ? -1 : 1;
  }
  return 0;
}

let headText;
try {
  headText = readFileSync(join(REPO_ROOT, CONF_REL), 'utf8');
} catch {
  fail(`Cannot read ${CONF_REL}.`);
}
const head = versionOf(headText, 'HEAD');

let base;
try {
  base = versionOf(readAtRef(BASE_REF), BASE_REF);
} catch {
  fail(
    `Cannot read ${CONF_REL} at ${BASE_REF}. The gate needs the default branch to ` +
      'compare against — check out with `fetch-depth: 0` (or set AEGIS_BASE_REF).',
  );
}

const headCode = versionCodeOf(head, 'HEAD');
if (headCode === null) {
  fail(
    `"version": "${head}" in ${CONF_REL} is not MAJOR.MINOR.PATCH, so the derived ` +
      'Android versionCode is not a monotonic integer. Use semver.',
  );
}

const cmp = compare(head, base);
if (cmp === null) {
  fail(`Cannot compare version "${head}" against "${base}" on ${BASE_REF} as semver.`);
}

if (cmp === 0) {
  // Not a release bump — nothing to enforce. Report and pass so ordinary PRs are
  // not gated on this.
  console.log(`version ${head} unchanged from ${BASE_REF} (versionCode ${headCode}).`);
} else if (cmp < 0) {
  fail(
    `version was DECREASED: ${base} (${BASE_REF}) -> ${head}. A lower versionCode ` +
      'means Android will refuse the install as a downgrade.',
  );
} else {
  const baseCode = versionCodeOf(base, BASE_REF);
  if (baseCode !== null && headCode <= baseCode) {
    fail(`versionCode did not increase: ${baseCode} (${BASE_REF}) -> ${headCode}.`);
  }
  console.log(`version ${base} -> ${head} (versionCode ${baseCode} -> ${headCode}).`);
}

// Cross-check the derived code against the file Tauri actually generated, when it
// is on disk. It is git-ignored and absent on a clean checkout, so this is a
// belt-and-braces assertion, not the gate.
const props = join(REPO_ROOT, PROPS_REL);
if (existsSync(props)) {
  const m = /^tauri\.android\.versionCode=(\d+)$/m.exec(readFileSync(props, 'utf8'));
  if (!m) {
    fail(`${PROPS_REL} has no parseable tauri.android.versionCode — regenerate it.`);
  } else if (Number(m[1]) !== headCode) {
    fail(
      `${PROPS_REL} says versionCode=${m[1]} but ${CONF_REL} version ${head} derives ` +
        `${headCode}. The generated file is stale — re-run the Android build.`,
    );
  } else {
    console.log(`${PROPS_REL} agrees (versionCode=${m[1]}).`);
  }
} else {
  console.log(`${PROPS_REL} not generated yet — skipped the cross-check.`);
}
